-- Narrow, reviewed additions. Never force UNKNOWN fields to become fiction.
local _,ns=...
local D=ns.AthenaLoreCodexInput
D.version='lore-11.0'
local classSource='https://news.blizzard.com/en-us/article/24304075/create-the-hero-you-want-to-be-in-world-of-warcraft-forever'
local forsakenSource='https://news.blizzard.com/en-us/article/24301511/wage-war-once-more-with-warcraft-iii-reforged-forsaken-kingdom'
local function enrich(title,field,text,url)
 for _,e in ipairs(D.entries) do if e.title==title then
  if not e.fields[field] or e.fields[field]=='UNKNOWN' then e.fields[field]=text;e.fieldSources=e.fieldSources or {};e.fieldSources[field]=url end
  return
 end end
end
enrich('The Forsaken','stakes','Freed from the Scourge, the Forsaken fought to establish a future beneath Lordaeron’s ruined kingdom.',forsakenSource)
enrich('The Forsaken','motivation','Under Sylvanas, the Forsaken sought vengeance against the Scourge and the Lich King.',classSource)
enrich('Undercity','context','The newly risen Forsaken established a foothold beneath the shattered surface of their former kingdom.',forsakenSource)
enrich('Night Elves','context','The night elves’ long isolation gave way to renewed conflict when the Burning Legion returned.',classSource)
enrich('The Tauren','relationships','Orcish aid against the centaur created a debt the tauren honored by joining the Horde.',classSource)
enrich('Gnomes','stakes','The loss of Gnomeregan left gnomish survivors seeking refuge with their dwarven allies.',classSource)
-- Stable places explicitly named in the bundled quest description atoms.
local function place(id,title,text,quest,hash,atoms)
 for _,e in ipairs(D.entries) do if e.title==title then return end end
 D.entries[#D.entries+1]={id=id,title=title,kind='place',category='landmarks',gate='HISTORICAL',aliases={title},
  fields={location=text},sourceURL='https://www.wowhead.com/classic/quest='..quest,
  reviewedSource={questID=quest,sourceHash=hash,atomIDs=atoms,truthScope='QUEST_SOURCE_GEOGRAPHY',personalExperienceProven=false}}
end
